  await prisma.fullExamQuestion.createMany({
    data: [
      { fullExamId: exam2.id, questionIndex: 1, questionText: 'A mechanically ventilated ARDS patient has a plateau pressure of 32 cmH2O and PEEP of 14 cmH2O. The driving pressure is:', choices: JSON.stringify({ A: '32 cmH2O', B: '18 cmH2O', C: '14 cmH2O', D: '46 cmH2O' }), correctChoice: 'B', explanationCorrect: 'Driving pressure = Plateau pressure - PEEP = 32 - 14 = 18 cmH2O. This exceeds the recommended threshold of 15 cmH2O and is associated with increased mortality.', explanationWrong: '32 is the plateau pressure. 14 is the PEEP. 46 is the sum, not the difference. Driving pressure is always Pplat minus PEEP.', topic: 'Advanced Mechanical Ventilation' },
      { fullExamId: exam2.id, questionIndex: 2, questionText: 'A pulmonary artery catheter shows PAWP of 22 mmHg and cardiac index of 1.8 L/min/m2. This pattern is most consistent with:', choices: JSON.stringify({ A: 'Septic shock', B: 'Cardiogenic shock', C: 'Hypovolemic shock', D: 'Neurogenic shock' }), correctChoice: 'B', explanationCorrect: 'Elevated PAWP (>18 mmHg) with low cardiac index (<2.2) is the hemodynamic hallmark of cardiogenic shock, indicating left ventricular failure with pulmonary congestion.', explanationWrong: 'Septic shock shows high CO with low SVR. Hypovolemic shock shows low PAWP. Neurogenic shock shows low SVR with bradycardia. High PAWP + low CI = cardiogenic.', topic: 'Hemodynamic Monitoring' },
      { fullExamId: exam2.id, questionIndex: 3, questionText: 'A patient has pH 7.52, PaCO2 48 mmHg, HCO3- 38 mEq/L. The primary disorder is:', choices: JSON.stringify({ A: 'Respiratory acidosis', B: 'Respiratory alkalosis', C: 'Metabolic acidosis', D: 'Metabolic alkalosis' }), correctChoice: 'D', explanationCorrect: 'Elevated pH with elevated HCO3- indicates metabolic alkalosis. The elevated PaCO2 of 48 represents appropriate respiratory compensation (hypoventilation to retain CO2).', explanationWrong: 'Respiratory acidosis would show low pH. Respiratory alkalosis would show low PaCO2. Metabolic acidosis would show low HCO3-. The elevated HCO3- drives the alkalosis.', topic: 'Advanced ABG Interpretation' },
      { fullExamId: exam2.id, questionIndex: 4, questionText: 'Which Berlin definition criterion requires bilateral opacities on chest imaging?', choices: JSON.stringify({ A: 'Timing criterion', B: 'Origin of edema criterion', C: 'Chest imaging criterion', D: 'Oxygenation criterion' }), correctChoice: 'C', explanationCorrect: 'The imaging criterion of the Berlin definition requires bilateral opacities not fully explained by effusions, lobar/lung collapse, or nodules on chest radiograph or CT scan.', explanationWrong: 'The timing criterion addresses onset within 7 days. Origin of edema excludes cardiac causes. Oxygenation uses P/F ratio. Bilateral opacities are the imaging requirement.', topic: 'ARDS Diagnosis and Management' },
      { fullExamId: exam2.id, questionIndex: 5, questionText: 'The SOFA (Sequential Organ Failure Assessment) score evaluates dysfunction in how many organ systems?', choices: JSON.stringify({ A: '4', B: '5', C: '6', D: '8' }), correctChoice: 'C', explanationCorrect: 'SOFA scores six organ systems: respiratory (P/F ratio), coagulation (platelets), liver (bilirubin), cardiovascular (MAP/vasopressors), neurological (GCS), and renal (creatinine/urine output).', explanationWrong: 'The SOFA score specifically evaluates 6 organ systems, not 4, 5, or 8. Each system is scored 0-4, giving a maximum total score of 24.', topic: 'Sepsis and Septic Shock' },
      { fullExamId: exam2.id, questionIndex: 6, questionText: 'Intrapulmonary shunt (Qs/Qt) is elevated when:', choices: JSON.stringify({ A: 'Dead space increases', B: 'Bronchospasm occurs', C: 'Tidal volume decreases', D: 'Blood passes through non-ventilated alveoli' }), correctChoice: 'D', explanationCorrect: 'Intrapulmonary shunt occurs when blood flows through capillaries adjacent to non-ventilated (collapsed or fluid-filled) alveoli, resulting in venous admixture. Normal shunt is 2-5%.', explanationWrong: 'Increased dead space is the opposite of shunt (ventilation without perfusion). Bronchospasm increases resistance. Decreased VT reduces ventilation but is not the definition of shunt.', topic: 'Acute Respiratory Failure' },
      { fullExamId: exam2.id, questionIndex: 7, questionText: 'During a pressure-support ventilation (PSV) spontaneous breathing trial, the recommended pressure support level is:', choices: JSON.stringify({ A: '5-8 cmH2O', B: '15-20 cmH2O', C: '0 cmH2O (T-piece equivalent)', D: '25-30 cmH2O' }), correctChoice: 'A', explanationCorrect: 'An SBT using PSV typically uses 5-8 cmH2O of pressure support to compensate for the resistance of the endotracheal tube. Some protocols use 0 cmH2O (CPAP or T-piece) for a more rigorous trial.', explanationWrong: '15-30 cmH2O provides significant ventilatory support and does not simulate spontaneous breathing. While 0 cmH2O is used, 5-8 is the standard PSV-based SBT.', topic: 'Weaning Protocols and SBTs' },
      { fullExamId: exam2.id, questionIndex: 8, questionText: 'CPAP is indicated for which condition in the ICU?', choices: JSON.stringify({ A: 'Hypovolemic shock', B: 'Acute cardiogenic pulmonary edema', C: 'Tension pneumothorax', D: 'Complete upper airway obstruction' }), correctChoice: 'B', explanationCorrect: 'CPAP reduces preload and afterload while improving oxygenation through alveolar recruitment, making it highly effective for acute cardiogenic pulmonary edema. It reduces intubation rates and mortality.', explanationWrong: 'Hypovolemic shock needs fluids. Tension pneumothorax needs decompression. Complete airway obstruction requires surgical airway. CPAP is specifically beneficial in cardiogenic pulmonary edema.', topic: 'NIV in Critical Care' },
      { fullExamId: exam2.id, questionIndex: 9, questionText: 'The PROSEVA trial studying prone positioning in severe ARDS demonstrated:', choices: JSON.stringify({ A: 'Significant reduction in 28-day mortality', B: 'No difference in mortality', C: 'Increased complication rates without benefit', D: 'Benefit only in mild ARDS' }), correctChoice: 'A', explanationCorrect: 'The PROSEVA trial showed 28-day mortality of 16% in prone vs 32.8% in supine group (P<0.001), establishing a strong mortality benefit for prone positioning in severe ARDS.', explanationWrong: 'PROSEVA demonstrated a clear mortality benefit, not equivalence or harm. The benefit was in severe ARDS (P/F < 150), not mild ARDS.', topic: 'Prone Positioning' },
      { fullExamId: exam2.id, questionIndex: 10, questionText: 'Succinylcholine differs from nondepolarizing NMBAs because it:', choices: JSON.stringify({ A: 'Has a slower onset of action', B: 'Does not require hepatic metabolism', C: 'Causes initial muscle fasciculations followed by paralysis', D: 'Has a longer duration of action' }), correctChoice: 'C', explanationCorrect: 'Succinylcholine is a depolarizing NMBA that mimics acetylcholine, causing initial fasciculations (Phase I block) before producing paralysis. It has rapid onset (30-60 seconds) and ultra-short duration (5-10 minutes).', explanationWrong: 'Succinylcholine has faster onset, not slower. It is metabolized by plasma cholinesterase, not hepatic enzymes. Its duration is ultra-short (5-10 min), not long.', topic: 'Neuromuscular Blocking Agents' },
      { fullExamId: exam2.id, questionIndex: 11, questionText: 'The Behavioral Pain Scale (BPS) is used in the ICU to assess pain in:', choices: JSON.stringify({ A: 'Alert and oriented patients', B: 'Patients unable to self-report pain', C: 'Patients in the post-anesthesia recovery unit only', D: 'Pediatric patients exclusively' }), correctChoice: 'B', explanationCorrect: 'The BPS evaluates pain in patients who cannot self-report (intubated, sedated, or cognitively impaired) using three domains: facial expression, upper limb movements, and ventilator compliance.', explanationWrong: 'Alert patients can use the numeric rating scale. BPS is for ICU patients who cannot communicate, not limited to PACU or pediatrics.', topic: 'Sedation and Pain Management' },
      { fullExamId: exam2.id, questionIndex: 12, questionText: 'The most important modifiable risk factor for VAP is:', choices: JSON.stringify({ A: 'Patient age', B: 'Severity of illness', C: 'Diagnosis on admission', D: 'Duration of mechanical ventilation' }), correctChoice: 'D', explanationCorrect: 'Duration of mechanical ventilation is the strongest modifiable risk factor for VAP. Each additional day of ventilation increases VAP risk by approximately 1-3%. Early liberation from the ventilator is key to prevention.', explanationWrong: 'Age, illness severity, and admission diagnosis are non-modifiable risk factors. Duration of ventilation is modifiable through daily SBTs, sedation protocols, and early mobilization.', topic: 'VAP Prevention' },
      { fullExamId: exam2.id, questionIndex: 13, questionText: 'The primary indication for VA ECMO (as opposed to VV ECMO) is:', choices: JSON.stringify({ A: 'Isolated respiratory failure with preserved cardiac function', B: 'COPD exacerbation', C: 'Status asthmaticus', D: 'Cardiogenic shock or combined cardiopulmonary failure' }), correctChoice: 'D', explanationCorrect: 'VA ECMO provides both cardiac and respiratory support by draining venous blood and returning oxygenated blood to the arterial system, bypassing both the lungs and heart. It is indicated when cardiac support is needed.', explanationWrong: 'Isolated respiratory failure uses VV ECMO. COPD and asthma exacerbations rarely need ECMO. VA ECMO is specifically for cardiac failure or combined cardiopulmonary failure.', topic: 'ECMO' },
      { fullExamId: exam2.id, questionIndex: 14, questionText: 'The primary survey in trauma assessment (ATLS) follows which sequence?', choices: JSON.stringify({ A: 'History, physical exam, imaging, labs', B: 'Airway, Breathing, Circulation, Disability, Exposure', C: 'Chest X-ray, CT scan, ultrasound, MRI', D: 'Neurological assessment, respiratory assessment, cardiac assessment' }), correctChoice: 'B', explanationCorrect: 'The ATLS primary survey follows ABCDE: Airway with cervical spine protection, Breathing, Circulation with hemorrhage control, Disability (neurological status), and Exposure/Environment.', explanationWrong: 'History and detailed imaging are part of the secondary survey. The primary survey is a rapid systematic assessment following ABCDE to identify life-threatening conditions.', topic: 'Chest Trauma' },
      { fullExamId: exam2.id, questionIndex: 15, questionText: 'The Rule of Nines for burn assessment assigns what percentage to each upper extremity in an adult?', choices: JSON.stringify({ A: '18%', B: '14%', C: '9%', D: '1%' }), correctChoice: 'C', explanationCorrect: 'The Rule of Nines assigns 9% TBSA to each upper extremity (entire arm). Head = 9%, each lower extremity = 18%, anterior trunk = 18%, posterior trunk = 18%, perineum = 1%.', explanationWrong: '18% is each lower extremity or each side of the trunk. 14% applies to different pediatric calculations. 1% is the perineum. Each arm is 9%.', topic: 'Burns and Inhalation Injury' },
      { fullExamId: exam2.id, questionIndex: 16, questionText: 'Controlled oxygen therapy in acute COPD exacerbation targets an SpO2 of:', choices: JSON.stringify({ A: '88-92%', B: '95-100%', C: '75-80%', D: '98-100%' }), correctChoice: 'A', explanationCorrect: 'COPD patients should be titrated to SpO2 88-92% to avoid oxygen-induced hypercapnia. Excessive supplemental oxygen can suppress hypoxic ventilatory drive and worsen V/Q mismatch through release of hypoxic vasoconstriction.', explanationWrong: 'Targeting 95-100% risks oxygen-induced hypercapnia. 75-80% is too low. The 88-92% range balances adequate oxygenation while minimizing CO2 retention.', topic: 'Acute COPD Exacerbation' },
      { fullExamId: exam2.id, questionIndex: 17, questionText: 'Ketamine is sometimes used in status asthmaticus because:', choices: JSON.stringify({ A: 'It is a potent anti-inflammatory', B: 'It causes bronchodilation through sympathomimetic effects', C: 'It reduces mucus production', D: 'It directly inhibits mast cell degranulation' }), correctChoice: 'B', explanationCorrect: 'Ketamine causes bronchodilation through catecholamine release (sympathomimetic effect) and direct smooth muscle relaxation. It also provides sedation and analgesia, making it useful for intubation in severe asthma.', explanationWrong: 'Ketamine is not primarily anti-inflammatory, does not significantly reduce mucus, and does not inhibit mast cells. Its bronchodilatory effect is mediated by sympathomimetic mechanisms.', topic: 'Status Asthmaticus' },
      { fullExamId: exam2.id, questionIndex: 18, questionText: 'Right ventricular strain on ECG in pulmonary embolism is suggested by:', choices: JSON.stringify({ A: 'S1Q3T3 pattern', B: 'ST elevation in leads V1-V4', C: 'Left bundle branch block', D: 'Peaked P waves in lead II only' }), correctChoice: 'A', explanationCorrect: 'The S1Q3T3 pattern (S wave in lead I, Q wave and inverted T wave in lead III) suggests acute right heart strain from PE. It is present in only 10-20% of PE cases but is the most classic ECG finding.', explanationWrong: 'ST elevation in V1-V4 suggests anterior MI. LBBB is not specific for PE. Peaked P waves suggest right atrial enlargement but not acute PE. S1Q3T3 is the classic PE pattern.', topic: 'Pulmonary Embolism' },
      { fullExamId: exam2.id, questionIndex: 19, questionText: 'Thoracentesis should be performed when a pleural effusion occupies more than what percentage of the hemithorax on chest X-ray and the patient is symptomatic?', choices: JSON.stringify({ A: '10%', B: '15%', C: '5%', D: 'Any symptomatic effusion with diagnostic uncertainty warrants thoracentesis' }), correctChoice: 'D', explanationCorrect: 'Thoracentesis is indicated for any new, clinically significant pleural effusion to determine etiology (diagnostic) and for symptom relief in large effusions (therapeutic). There is no specific percentage threshold.', explanationWrong: 'While size matters for therapeutic drainage, diagnostic thoracentesis is based on clinical indication, not a specific percentage threshold. Any significant new effusion warrants sampling.', topic: 'Pleural Diseases' },
      { fullExamId: exam2.id, questionIndex: 20, questionText: 'Ventilator-associated events (VAE) are identified by a sustained increase in daily minimum PEEP or FiO2 after a period of stability lasting at least:', choices: JSON.stringify({ A: '12 hours', B: '1 day', C: '2 days of stable or decreasing settings', D: '5 days' }), correctChoice: 'C', explanationCorrect: 'The CDC VAE definition requires at least 2 calendar days of stable or decreasing ventilator settings (PEEP and FiO2) followed by a sustained increase for at least 2 calendar days.', explanationWrong: '12 hours, 1 day, and 5 days are not the correct stability period. The VAE algorithm requires a 2-day baseline of stability before detecting a worsening event.', topic: 'ICU Quality Metrics' },
      { fullExamId: exam2.id, questionIndex: 21, questionText: 'High-frequency oscillatory ventilation (HFOV) uses tidal volumes that are:', choices: JSON.stringify({ A: '10-12 mL/kg PBW', B: '6-8 mL/kg PBW', C: 'Smaller than anatomical dead space (1-3 mL/kg)', D: '15-20 mL/kg PBW' }), correctChoice: 'C', explanationCorrect: 'HFOV delivers very small tidal volumes (1-3 mL/kg, smaller than anatomical dead space) at very high frequencies (3-15 Hz), relying on augmented diffusion and other mechanisms for gas transport.', explanationWrong: '6-12 mL/kg are conventional ventilation volumes. 15-20 mL/kg are dangerously high. HFOV specifically uses sub-dead space tidal volumes.', topic: 'Advanced Mechanical Ventilation' },
      { fullExamId: exam2.id, questionIndex: 22, questionText: 'Stroke volume variation (SVV) is most reliable for predicting fluid responsiveness when:', choices: JSON.stringify({ A: 'The patient has atrial fibrillation', B: 'The patient is spontaneously breathing', C: 'The patient is on low-dose vasopressors', D: 'The patient is passively mechanically ventilated with VT ≥ 8 mL/kg and in sinus rhythm' }), correctChoice: 'D', explanationCorrect: 'SVV is reliable only during passive mechanical ventilation with adequate tidal volumes (≥8 mL/kg), regular cardiac rhythm, and closed chest. Spontaneous breathing, arrhythmias, and low VT invalidate SVV.', explanationWrong: 'Atrial fibrillation invalidates SVV. Spontaneous breathing causes variable intrathoracic pressure changes. Low-dose vasopressors may be present but the key requirements are passive ventilation and sinus rhythm.', topic: 'Hemodynamic Monitoring' },
      { fullExamId: exam2.id, questionIndex: 23, questionText: 'A patient has pH 7.10, PaCO2 24 mmHg, HCO3- 8 mEq/L, Na+ 142, Cl- 110. The anion gap is 24. The delta-delta ratio (delta AG / delta HCO3-) is:', choices: JSON.stringify({ A: '0.75 (concurrent non-anion gap metabolic acidosis present)', B: '1.0 (pure anion gap metabolic acidosis)', C: '0.75 (pure anion gap metabolic acidosis)', D: '2.0 (concurrent metabolic alkalosis present)' }), correctChoice: 'A', explanationCorrect: 'Delta AG = 24 - 12 = 12. Delta HCO3- = 24 - 8 = 16. Ratio = 12/16 = 0.75. A ratio < 1 suggests a concurrent non-anion gap metabolic acidosis alongside the AGMA. The elevated chloride (110) supports this.', explanationWrong: 'A ratio of 1.0 would indicate pure AGMA. A ratio > 2 suggests concurrent metabolic alkalosis. The ratio of 0.75 indicates a mixed anion gap and non-anion gap metabolic acidosis.', topic: 'Advanced ABG Interpretation' },
      { fullExamId: exam2.id, questionIndex: 24, questionText: 'Extravascular lung water (EVLW) measurement helps differentiate:', choices: JSON.stringify({ A: 'Obstructive vs restrictive lung disease', B: 'ARDS from cardiogenic pulmonary edema', C: 'Upper vs lower airway obstruction', D: 'Pleural effusion from pneumothorax' }), correctChoice: 'B', explanationCorrect: 'EVLW quantifies pulmonary edema fluid. Combined with pulmonary vascular permeability index (PVPI), it helps distinguish ARDS (high permeability edema) from cardiogenic pulmonary edema (hydrostatic edema).', explanationWrong: 'EVLW does not assess obstructive vs restrictive disease, airway obstruction, or pleural vs pneumothorax. It specifically quantifies lung water to characterize pulmonary edema.', topic: 'ARDS Diagnosis and Management' },
      { fullExamId: exam2.id, questionIndex: 25, questionText: 'Mean arterial pressure (MAP) target during initial sepsis resuscitation is:', choices: JSON.stringify({ A: '≥ 65 mmHg', B: '≥ 80 mmHg', C: '≥ 90 mmHg', D: '≥ 50 mmHg' }), correctChoice: 'A', explanationCorrect: 'The Surviving Sepsis Campaign recommends targeting MAP ≥ 65 mmHg during initial resuscitation. Higher targets may be considered in patients with chronic hypertension but are not routinely recommended.', explanationWrong: 'MAP targets of 80-90 are not standard SSC recommendations. MAP of 50 is inadequate for organ perfusion. The evidence-based target is ≥ 65 mmHg.', topic: 'Sepsis and Septic Shock' },
      { fullExamId: exam2.id, questionIndex: 26, questionText: 'Oxygen toxicity from prolonged high FiO2 exposure primarily causes:', choices: JSON.stringify({ A: 'Renal failure', B: 'Hepatic necrosis', C: 'Absorption atelectasis and diffuse alveolar damage', D: 'Cardiac arrhythmias' }), correctChoice: 'C', explanationCorrect: 'Prolonged FiO2 > 0.60 causes oxygen toxicity through formation of reactive oxygen species, leading to absorption atelectasis (nitrogen washout) and diffuse alveolar damage similar to ARDS.', explanationWrong: 'Oxygen toxicity primarily affects the lungs, not the kidneys, liver, or heart. Absorption atelectasis and oxidative alveolar injury are the main pulmonary manifestations.', topic: 'Acute Respiratory Failure' },
      { fullExamId: exam2.id, questionIndex: 27, questionText: 'The rapid shallow breathing index (RSBI) is calculated as:', choices: JSON.stringify({ A: 'Tidal volume divided by respiratory rate', B: 'Respiratory rate divided by tidal volume (in liters)', C: 'Minute ventilation divided by respiratory rate', D: 'Peak flow divided by tidal volume' }), correctChoice: 'B', explanationCorrect: 'RSBI = f/VT (respiratory rate in breaths/min divided by tidal volume in liters). Values < 105 predict successful extubation. For example, RR 20 / VT 0.4L = RSBI of 50 (favorable).', explanationWrong: 'VT/RR would be the inverse. MV/RR equals VT. Peak flow/VT is not a standard index. RSBI specifically uses RR/VT in liters.', topic: 'Weaning Protocols and SBTs' },
      { fullExamId: exam2.id, questionIndex: 28, questionText: 'Average volume-assured pressure support (AVAPS) on NIV automatically adjusts:', choices: JSON.stringify({ A: 'FiO2 to maintain SpO2', B: 'EPAP to maintain airway patency', C: 'Backup respiratory rate', D: 'IPAP to achieve a target tidal volume' }), correctChoice: 'D', explanationCorrect: 'AVAPS automatically adjusts IPAP within a set range to achieve and maintain a target tidal volume, combining the comfort of pressure support with the volume guarantee of volume ventilation.', explanationWrong: 'FiO2 is manually set. EPAP adjustment is a feature of auto-CPAP, not AVAPS. Backup rate is set, not auto-adjusted. AVAPS specifically targets tidal volume by adjusting IPAP.', topic: 'NIV in Critical Care' },
      { fullExamId: exam2.id, questionIndex: 29, questionText: 'During prone positioning, endotracheal tube complications are minimized by:', choices: JSON.stringify({ A: 'Removing all tube securing devices during positioning', B: 'Deflating the cuff during the turn', C: 'Using shorter ETTs', D: 'Ensuring secure tube fixation and verifying position before and after turning' }), correctChoice: 'D', explanationCorrect: 'Secure tube fixation, position verification (depth marking, bilateral breath sounds, EtCO2), and careful team coordination during the turn prevent accidental extubation, the most feared complication of proning.', explanationWrong: 'Removing securing devices or deflating the cuff increases extubation risk. Shorter ETTs may dislodge more easily. Secure fixation and verification are the standard safety measures.', topic: 'Prone Positioning' },
      { fullExamId: exam2.id, questionIndex: 30, questionText: 'Reversal of rocuronium-induced neuromuscular blockade is best achieved with:', choices: JSON.stringify({ A: 'Flumazenil', B: 'Sugammadex', C: 'Naloxone', D: 'Physostigmine' }), correctChoice: 'B', explanationCorrect: 'Sugammadex is a modified gamma-cyclodextrin that encapsulates rocuronium (and vecuronium), providing rapid and complete reversal of neuromuscular blockade within 2-3 minutes.', explanationWrong: 'Flumazenil reverses benzodiazepines. Naloxone reverses opioids. Physostigmine is a cholinesterase inhibitor. Sugammadex specifically binds aminosteroid NMBAs.', topic: 'Neuromuscular Blocking Agents' },
      { fullExamId: exam2.id, questionIndex: 31, questionText: 'The Critical-Care Pain Observation Tool (CPOT) includes which domain?', choices: JSON.stringify({ A: 'Blood pressure response', B: 'Pupil reactivity', C: 'Facial expression', D: 'Urine output' }), correctChoice: 'C', explanationCorrect: 'CPOT evaluates four domains: facial expression, body movements, compliance with ventilator (or vocalization in non-intubated), and muscle tension. Each is scored 0-2 for a total of 0-8.', explanationWrong: 'Blood pressure, pupil reactivity, and urine output are not CPOT domains. CPOT uses behavioral observations specifically designed for critically ill patients.', topic: 'Sedation and Pain Management' },
      { fullExamId: exam2.id, questionIndex: 32, questionText: 'Oral care with chlorhexidine in the VAP prevention bundle targets:', choices: JSON.stringify({ A: 'Reduction of oropharyngeal bacterial colonization', B: 'Prevention of dental caries', C: 'Reduction of gastric colonization', D: 'Treatment of oral candidiasis' }), correctChoice: 'A', explanationCorrect: 'Chlorhexidine oral care reduces oropharyngeal bacterial colonization, decreasing the pathogenic organisms available for aspiration into the lower airway. This is a core component of the VAP prevention bundle.', explanationWrong: 'Chlorhexidine does not target gastric colonization, prevent dental caries, or treat oral candidiasis. Its mechanism is reduction of oropharyngeal bacterial burden.', topic: 'VAP Prevention' },
      { fullExamId: exam2.id, questionIndex: 33, questionText: 'ECMO circuit anticoagulation is most commonly maintained with:', choices: JSON.stringify({ A: 'Warfarin', B: 'Unfractionated heparin', C: 'Aspirin', D: 'Enoxaparin' }), correctChoice: 'B', explanationCorrect: 'Unfractionated heparin is the standard anticoagulant for ECMO circuits, titrated to an activated clotting time (ACT) of 180-220 seconds or anti-Xa levels. Bivalirudin is an alternative for heparin-induced thrombocytopenia.', explanationWrong: 'Warfarin has delayed onset and is impractical for ECMO. Aspirin is antiplatelet, not anticoagulant. LMWH is difficult to monitor and reverse. UFH is the standard for ECMO.', topic: 'ECMO' },
      { fullExamId: exam2.id, questionIndex: 34, questionText: 'A focused assessment with sonography for trauma (FAST) exam evaluates for free fluid in which locations?', choices: JSON.stringify({ A: 'Hepatorenal space, splenorenal space, pelvis, and pericardium', B: 'Lungs, liver, and kidneys', C: 'Brain, spine, and thorax', D: 'Pleural space only' }), correctChoice: 'A', explanationCorrect: 'The FAST exam uses four sonographic windows: right upper quadrant (hepatorenal/Morison pouch), left upper quadrant (splenorenal), suprapubic (pelvis), and subxiphoid (pericardium) to detect free fluid.', explanationWrong: 'FAST does not evaluate the brain or spine. While extended FAST (eFAST) includes pleural evaluation, the standard FAST examines 4 specific areas for free fluid.', topic: 'Chest Trauma' },
      { fullExamId: exam2.id, questionIndex: 35, questionText: 'Upper airway edema from inhalation injury typically peaks at:', choices: JSON.stringify({ A: '1-2 hours post-injury', B: '6-8 hours post-injury', C: '12-14 hours post-injury', D: '24-48 hours post-injury' }), correctChoice: 'D', explanationCorrect: 'Airway edema from thermal/inhalation injury peaks at 24-48 hours post-exposure, which is why early intubation is recommended when inhalation injury is suspected, before edema makes intubation impossible.', explanationWrong: '1-8 hours is too early for peak edema. While edema begins within hours, it continues to worsen and peaks at 24-48 hours, making delayed intubation potentially impossible.', topic: 'Burns and Inhalation Injury' },
      { fullExamId: exam2.id, questionIndex: 36, questionText: 'NIV for acute COPD exacerbation has been shown to reduce:', choices: JSON.stringify({ A: 'Length of hospital stay only', B: 'Cost of care only', C: 'Intubation rate, ICU mortality, and hospital length of stay', D: 'Antibiotic requirements' }), correctChoice: 'C', explanationCorrect: 'Strong evidence shows NIV in acute COPD exacerbation reduces intubation rates (by ~65%), ICU mortality, hospital length of stay, and complications compared to standard medical therapy alone.', explanationWrong: 'NIV benefits extend well beyond just LOS or cost reduction. The multiple demonstrated benefits include reduced intubation, mortality, and complications. Antibiotic requirements are not directly affected.', topic: 'Acute COPD Exacerbation' },
      { fullExamId: exam2.id, questionIndex: 37, questionText: 'In mechanically ventilated status asthmaticus patients, the recommended ventilation strategy emphasizes:', choices: JSON.stringify({ A: 'High respiratory rates to normalize PaCO2', B: 'Large tidal volumes to overcome bronchospasm', C: 'Low respiratory rate, prolonged expiratory time, and permissive hypercapnia', D: 'High PEEP to splint airways open' }), correctChoice: 'C', explanationCorrect: 'Ventilation strategy in status asthmaticus prioritizes avoiding dynamic hyperinflation: low RR (10-14), prolonged expiratory time (I:E 1:3 to 1:5), moderate VT (6-8 mL/kg), and permissive hypercapnia.', explanationWrong: 'High rates worsen air trapping. Large VTs increase hyperinflation risk. High PEEP can worsen auto-PEEP. The strategy minimizes air trapping by allowing adequate expiration.', topic: 'Status Asthmaticus' },
      { fullExamId: exam2.id, questionIndex: 38, questionText: 'Thrombolytic therapy for pulmonary embolism is indicated in:', choices: JSON.stringify({ A: 'All patients with confirmed PE', B: 'Subsegmental PE only', C: 'Chronic PE with pulmonary hypertension', D: 'Massive PE with hemodynamic instability' }), correctChoice: 'D', explanationCorrect: 'Systemic thrombolysis (tPA) is indicated for massive PE with hemodynamic instability (SBP < 90 mmHg) or cardiac arrest, where the benefit of clot dissolution outweighs bleeding risk.', explanationWrong: 'Not all PE requires thrombolysis. Subsegmental PE may not even need anticoagulation. Chronic PE is treated surgically. Thrombolysis is reserved for hemodynamically unstable massive PE.', topic: 'Pulmonary Embolism' },
      { fullExamId: exam2.id, questionIndex: 39, questionText: 'An empyema is characterized by pleural fluid with:', choices: JSON.stringify({ A: 'Positive Gram stain or culture, pH < 7.20, and/or frank pus', B: 'pH > 7.40 and glucose > 100 mg/dL', C: 'Transudative characteristics', D: 'Chylomicrons and elevated triglycerides' }), correctChoice: 'A', explanationCorrect: 'Empyema is infected pleural fluid characterized by positive cultures/Gram stain, pH < 7.20, glucose < 40 mg/dL, elevated LDH, or grossly purulent fluid. It requires chest tube drainage.', explanationWrong: 'High pH and glucose are normal values. Transudative fluid is not infected. Chylomicrons indicate chylothorax. Empyema is defined by infection markers in pleural fluid.', topic: 'Pleural Diseases' },
      { fullExamId: exam2.id, questionIndex: 40, questionText: 'The ICU Liberation (A-F) Bundle includes which component?', choices: JSON.stringify({ A: 'Antibiotic stewardship', B: 'Assess, prevent, and manage pain', C: 'Advanced imaging protocols', D: 'Arterial line placement' }), correctChoice: 'B', explanationCorrect: 'The ABCDEF bundle includes: Assess/prevent/manage pain (A), Both SAT and SBT (B), Choice of analgesia and sedation (C), Delirium assessment/prevention (D), Early mobility (E), and Family engagement (F).', explanationWrong: 'Antibiotic stewardship, advanced imaging, and arterial lines are not components of the ABCDEF bundle. The bundle focuses on pain, sedation, delirium, mobility, and family engagement.', topic: 'ICU Quality Metrics' },
      { fullExamId: exam2.id, questionIndex: 41, questionText: 'Transpulmonary pressure is calculated as:', choices: JSON.stringify({ A: 'Airway pressure minus esophageal pressure', B: 'Peak pressure minus plateau pressure', C: 'PEEP minus auto-PEEP', D: 'Mean airway pressure minus atmospheric pressure' }), correctChoice: 'A', explanationCorrect: 'Transpulmonary pressure = airway pressure - pleural pressure (estimated by esophageal pressure). This isolates the pressure distending the lung from chest wall effects, useful in obese or abdominal compartment syndrome patients.', explanationWrong: 'PIP minus Pplat is resistive pressure. PEEP minus auto-PEEP is not a standard calculation. MAP minus atmospheric is not transpulmonary. Esophageal pressure estimates pleural pressure.', topic: 'Advanced Mechanical Ventilation' },
      { fullExamId: exam2.id, questionIndex: 42, questionText: 'Central venous pressure (CVP) is measured at which anatomical location?', choices: JSON.stringify({ A: 'Left atrium', B: 'Pulmonary artery', C: 'Junction of superior vena cava and right atrium', D: 'Aortic arch' }), correctChoice: 'C', explanationCorrect: 'CVP is measured at the junction of the SVC and right atrium via the proximal port of a PA catheter or a central venous catheter. Normal CVP is 2-6 mmHg. It reflects right ventricular preload.', explanationWrong: 'Left atrial pressure is estimated by PAWP. Pulmonary artery pressure is measured at the distal PA port. The aortic arch measures systemic arterial pressure.', topic: 'Hemodynamic Monitoring' },
      { fullExamId: exam2.id, questionIndex: 43, questionText: 'A patient with diabetic ketoacidosis has pH 7.20, PaCO2 20 mmHg, HCO3- 8 mEq/L. After treatment, pH is 7.35 with PaCO2 35 and HCO3- 19. Which change occurred?', choices: JSON.stringify({ A: 'Development of respiratory alkalosis', B: 'Resolution of metabolic acidosis with normalizing compensation', C: 'New metabolic alkalosis', D: 'Worsening of the original disorder' }), correctChoice: 'B', explanationCorrect: 'The rising HCO3- (8 to 19) with rising PaCO2 (20 to 35) and improving pH shows resolution of the metabolic acidosis with appropriate reduction in compensatory hyperventilation as the acidosis resolves.', explanationWrong: 'The PaCO2 rise is appropriate as compensation wanes with improving acidosis, not a new respiratory process. HCO3- is still below normal, so no alkalosis. The disorder is improving.', topic: 'Advanced ABG Interpretation' },
      { fullExamId: exam2.id, questionIndex: 44, questionText: 'Dead space fraction (VD/VT) in ARDS is typically:', choices: JSON.stringify({ A: 'Decreased below normal', B: 'Normal (0.30-0.35)', C: 'Not measurable', D: 'Elevated (often > 0.50-0.60)' }), correctChoice: 'D', explanationCorrect: 'ARDS significantly increases dead space through pulmonary vascular injury, micro-thrombosis, and heterogeneous ventilation. VD/VT > 0.60 is associated with higher mortality in ARDS.', explanationWrong: 'Dead space is not decreased or normal in ARDS. It is readily measurable via volumetric capnography. Elevated dead space is both a hallmark and prognostic marker of ARDS.', topic: 'ARDS Diagnosis and Management' },
      { fullExamId: exam2.id, questionIndex: 45, questionText: 'Vasopressin is added as a second-line vasopressor in septic shock to:', choices: JSON.stringify({ A: 'Replace norepinephrine entirely', B: 'Increase heart rate', C: 'Provide anti-inflammatory effects', D: 'Allow norepinephrine dose reduction and restore vascular tone through V1 receptors' }), correctChoice: 'D', explanationCorrect: 'Vasopressin (0.03-0.04 units/min) is added to norepinephrine in septic shock to provide catecholamine-sparing effects and restore vascular tone through V1 receptor-mediated vasoconstriction, as vasopressin levels are depleted in sepsis.', explanationWrong: 'Vasopressin supplements, not replaces, norepinephrine. It does not increase heart rate (no beta effect). Anti-inflammatory effects are not the primary indication.', topic: 'Sepsis and Septic Shock' },
      { fullExamId: exam2.id, questionIndex: 46, questionText: 'The alveolar gas equation is used to calculate:', choices: JSON.stringify({ A: 'Arterial oxygen content', B: 'Expected alveolar PO2 (PAO2)', C: 'Cardiac output', D: 'Minute ventilation' }), correctChoice: 'B', explanationCorrect: 'The alveolar gas equation: PAO2 = FiO2(PB - PH2O) - PaCO2/RQ calculates the expected alveolar oxygen tension, which is then used to calculate the A-a gradient (PAO2 - PaO2).', explanationWrong: 'Arterial O2 content uses CaO2 equation. Cardiac output uses Fick or thermodilution. Minute ventilation = RR x VT. The alveolar gas equation specifically calculates PAO2.', topic: 'Acute Respiratory Failure' },
      { fullExamId: exam2.id, questionIndex: 47, questionText: 'A 30-minute spontaneous breathing trial is considered equivalent to a:', choices: JSON.stringify({ A: '10-minute trial', B: '60-minute trial', C: '120-minute trial', D: 'There is no equivalence; 120 minutes is always required' }), correctChoice: 'C', explanationCorrect: 'Studies have shown that a 30-minute SBT is non-inferior to a 120-minute SBT for predicting extubation success. Current guidelines support either duration, with many centers using 30-minute trials.', explanationWrong: '10 minutes is too brief. While 120 minutes was traditional, evidence shows 30 minutes is equivalent. There is strong evidence supporting the equivalence of shorter trials.', topic: 'Weaning Protocols and SBTs' },
      { fullExamId: exam2.id, questionIndex: 48, questionText: 'Helmet NIV compared to face mask NIV offers which advantage?', choices: JSON.stringify({ A: 'Better seal with reduced air leak and improved patient tolerance', B: 'Lower cost', C: 'Easier application', D: 'Higher maximum pressure delivery' }), correctChoice: 'A', explanationCorrect: 'Helmet NIV offers better patient tolerance, reduced skin breakdown (no facial contact), improved seal with reduced leak, and has shown improved outcomes in ARDS patients compared to face mask NIV.', explanationWrong: 'Helmets are generally more expensive. They can be more complex to apply. Pressure delivery may be similar. The main advantages are tolerance, reduced facial pressure injury, and better seal.', topic: 'NIV in Critical Care' },
      { fullExamId: exam2.id, questionIndex: 49, questionText: 'Prone positioning improves oxygenation in ARDS through all of the following mechanisms EXCEPT:', choices: JSON.stringify({ A: 'Improved V/Q matching', B: 'Increased bronchial smooth muscle relaxation', C: 'Recruitment of dorsal lung regions', D: 'Reduced compression of lung by the heart' }), correctChoice: 'B', explanationCorrect: 'Bronchial smooth muscle relaxation is NOT a mechanism of prone positioning. Prone positioning improves oxygenation through V/Q matching, dorsal lung recruitment, reduced cardiac compression, and improved secretion drainage.', explanationWrong: 'V/Q matching improvement, dorsal recruitment, and reduced cardiac compression are all mechanisms of prone positioning benefit. Bronchial smooth muscle relaxation is not related to positioning.', topic: 'Prone Positioning' },
      { fullExamId: exam2.id, questionIndex: 50, questionText: 'The most common adverse effect of neuromuscular blocking agents in the ICU is:', choices: JSON.stringify({ A: 'Prolonged paralysis and ICU-acquired weakness', B: 'Malignant hyperthermia', C: 'Bronchospasm', D: 'Hypertension' }), correctChoice: 'A', explanationCorrect: 'Prolonged paralysis and ICU-acquired weakness (critical illness myopathy/polyneuropathy) are the most common adverse effects, particularly with prolonged infusions and concomitant corticosteroid use.', explanationWrong: 'Malignant hyperthermia is rare and primarily with succinylcholine. Bronchospasm is uncommon. Hypertension is not a typical NMBA side effect. Prolonged weakness is the most significant concern.', topic: 'Neuromuscular Blocking Agents' },
      { fullExamId: exam2.id, questionIndex: 51, questionText: 'The target RASS score for most mechanically ventilated ICU patients per PADIS guidelines is:', choices: JSON.stringify({ A: '-5 (unarousable)', B: '-3 to -4 (deep sedation)', C: '+2 to +3 (agitated)', D: '0 to -2 (light sedation)' }), correctChoice: 'D', explanationCorrect: 'PADIS guidelines recommend targeting light sedation (RASS 0 to -2) for most mechanically ventilated patients, as deep sedation is associated with increased delirium, prolonged ventilation, and higher mortality.', explanationWrong: 'Deep sedation (-3 to -5) is associated with worse outcomes. Agitation (+2 to +3) is unsafe. Light sedation (0 to -2) provides comfort while minimizing sedation-related complications.', topic: 'Sedation and Pain Management' },
      { fullExamId: exam2.id, questionIndex: 52, questionText: 'Endotracheal tube cuff pressure should be maintained at:', choices: JSON.stringify({ A: '10-15 cmH2O', B: '40-50 cmH2O', C: '20-30 cmH2O', D: '5-10 cmH2O' }), correctChoice: 'C', explanationCorrect: 'ETT cuff pressure should be maintained at 20-30 cmH2O (15-22 mmHg). Pressures < 20 allow micro-aspiration and increase VAP risk. Pressures > 30 can cause tracheal mucosal ischemia and necrosis.', explanationWrong: '10-15 is too low, risking aspiration. 40-50 is too high, risking tracheal injury. 5-10 provides no seal. The 20-30 range balances aspiration prevention and mucosal safety.', topic: 'VAP Prevention' },
      { fullExamId: exam2.id, questionIndex: 53, questionText: 'Harlequin syndrome in VA ECMO with femoral cannulation refers to:', choices: JSON.stringify({ A: 'Skin rash from heparin allergy', B: 'Bilateral lower extremity cyanosis', C: 'Differential oxygenation between upper and lower body', D: 'Circuit failure with blood leak' }), correctChoice: 'C', explanationCorrect: 'Harlequin (North-South) syndrome occurs in femoral VA ECMO when the native heart ejects poorly oxygenated blood to the upper body while ECMO supplies oxygenated blood to the lower body, causing differential cyanosis.', explanationWrong: 'It is not an allergic reaction, isolated limb ischemia, or circuit failure. Harlequin syndrome is differential oxygenation due to competing flows from the heart and ECMO circuit.', topic: 'ECMO' },
      { fullExamId: exam2.id, questionIndex: 54, questionText: 'Massive hemoptysis in chest trauma is defined as expectoration of more than:', choices: JSON.stringify({ A: '500-600 mL of blood in 24 hours', B: '50 mL of blood in 24 hours', C: '10 mL of blood in 24 hours', D: '1000 mL in 1 hour' }), correctChoice: 'A', explanationCorrect: 'Massive hemoptysis is generally defined as >500-600 mL of blood in 24 hours or >100 mL/hour. It is a life-threatening emergency requiring airway protection, possible double-lumen intubation, and bronchial artery embolization or surgery.', explanationWrong: '50 mL and 10 mL are submassive amounts. 1000 mL/hour is catastrophic but not the standard definition threshold. The accepted definition is >500-600 mL in 24 hours.', topic: 'Chest Trauma' },
      { fullExamId: exam2.id, questionIndex: 55, questionText: 'The treatment for carbon monoxide poisoning involves:', choices: JSON.stringify({ A: '100% oxygen via non-rebreather mask or hyperbaric oxygen', B: 'Low-flow nasal cannula at 2 L/min', C: 'Inhaled bronchodilators', D: 'IV methylene blue' }), correctChoice: 'A', explanationCorrect: '100% oxygen displaces CO from hemoglobin, reducing the half-life of COHb from 4-6 hours on room air to 60-90 minutes. Hyperbaric oxygen (2.5-3 ATA) further reduces it to 15-30 minutes.', explanationWrong: 'Low-flow O2 is insufficient. Bronchodilators do not address CO binding. Methylene blue treats methemoglobinemia, not CO poisoning. High-concentration oxygen is the specific treatment.', topic: 'Burns and Inhalation Injury' },
      { fullExamId: exam2.id, questionIndex: 56, questionText: 'Long-term oxygen therapy (LTOT) in COPD is indicated when resting PaO2 is:', choices: JSON.stringify({ A: '≤ 65 mmHg', B: '≤ 55 mmHg or 56-59 with cor pulmonale or polycythemia', C: '≤ 70 mmHg', D: '≤ 80 mmHg' }), correctChoice: 'B', explanationCorrect: 'LTOT is indicated for PaO2 ≤ 55 mmHg (or SpO2 ≤ 88%), or PaO2 56-59 mmHg with evidence of cor pulmonale, pulmonary hypertension, or polycythemia (Hct > 55%). LTOT improves survival in qualifying patients.', explanationWrong: '65, 70, and 80 mmHg are above the threshold for LTOT. The landmark NOTT and MRC trials established the ≤ 55 mmHg criterion with specific exceptions for 56-59 mmHg.', topic: 'Acute COPD Exacerbation' },
      { fullExamId: exam2.id, questionIndex: 57, questionText: 'Inhaled epinephrine in status asthmaticus works by:', choices: JSON.stringify({ A: 'Stimulating beta-2 receptors causing bronchodilation and alpha-1 receptors reducing mucosal edema', B: 'Blocking muscarinic receptors', C: 'Inhibiting phosphodiesterase', D: 'Blocking leukotriene receptors' }), correctChoice: 'A', explanationCorrect: 'Racemic or L-epinephrine provides bronchodilation via beta-2 stimulation and reduces airway mucosal edema via alpha-1 vasoconstriction, offering dual benefit in severe bronchospasm with mucosal swelling.', explanationWrong: 'Muscarinic blockade is the mechanism of ipratropium. PDE inhibition is theophylline mechanism. Leukotriene blockade is montelukast. Epinephrine works through adrenergic receptor stimulation.', topic: 'Status Asthmaticus' },
      { fullExamId: exam2.id, questionIndex: 58, questionText: 'Right heart failure from acute PE is assessed bedside using:', choices: JSON.stringify({ A: 'Chest X-ray alone', B: 'Arterial blood gas', C: 'Bedside echocardiography', D: 'Serum albumin level' }), correctChoice: 'C', explanationCorrect: 'Bedside echocardiography rapidly assesses RV dilation, RV dysfunction (McConnell sign), tricuspid regurgitation, and septal bowing, which are key findings in hemodynamically significant PE with right heart strain.', explanationWrong: 'CXR is often normal in PE. ABG shows hypoxemia but not RV function. Albumin is irrelevant. Echocardiography directly visualizes right heart structure and function.', topic: 'Pulmonary Embolism' },
      { fullExamId: exam2.id, questionIndex: 59, questionText: 'Complicated parapneumonic effusion requiring chest tube drainage is indicated when pleural fluid pH is:', choices: JSON.stringify({ A: '> 7.40', B: '< 7.20', C: '7.30-7.40', D: '> 7.60' }), correctChoice: 'B', explanationCorrect: 'Pleural fluid pH < 7.20 indicates a complicated parapneumonic effusion at risk for empyema formation. Drainage is indicated along with antibiotics. Other drainage criteria include glucose < 40 or positive Gram stain/culture.', explanationWrong: 'pH > 7.30 suggests uncomplicated effusion that may resolve with antibiotics alone. The < 7.20 threshold triggers drainage to prevent progression to empyema.', topic: 'Pleural Diseases' },
      { fullExamId: exam2.id, questionIndex: 60, questionText: 'Catheter-associated urinary tract infection (CAUTI) prevention in the ICU primarily involves:', choices: JSON.stringify({ A: 'Prophylactic antibiotics while catheter is in place', B: 'Daily bladder irrigation with antiseptic solution', C: 'Routine urine cultures every 48 hours', D: 'Prompt removal of unnecessary urinary catheters' }), correctChoice: 'D', explanationCorrect: 'Prompt removal of unnecessary urinary catheters is the primary CAUTI prevention strategy. Daily review of catheter necessity and early removal are the most effective interventions, reducing catheter days and infection risk.', explanationWrong: 'Prophylactic antibiotics promote resistance. Bladder irrigation is not standard. Routine cultures lead to treatment of asymptomatic bacteriuria. Early catheter removal is the key prevention strategy.', topic: 'ICU Quality Metrics' },
      { fullExamId: exam2.id, questionIndex: 61, questionText: 'Neurally adjusted ventilatory assist (NAVA) mode uses which signal to trigger and cycle breaths?', choices: JSON.stringify({ A: 'Airway pressure changes', B: 'Flow changes at the airway', C: 'Chest wall impedance', D: 'Electrical activity of the diaphragm (Edi)' }), correctChoice: 'D', explanationCorrect: 'NAVA uses the electrical activity of the diaphragm (Edi), measured via an esophageal catheter with electrodes positioned at the crural diaphragm, to trigger and proportionally assist each breath.', explanationWrong: 'Airway pressure and flow triggering are used in conventional modes. Chest wall impedance is not used for ventilator triggering. Edi provides the most direct measure of respiratory neural drive.', topic: 'Advanced Mechanical Ventilation' },
      { fullExamId: exam2.id, questionIndex: 62, questionText: 'The pulmonary artery occlusion pressure (PAOP/PAWP) reflects:', choices: JSON.stringify({ A: 'Right ventricular end-diastolic pressure', B: 'Left atrial pressure and left ventricular end-diastolic pressure', C: 'Pulmonary vascular resistance', D: 'Right atrial pressure' }), correctChoice: 'B', explanationCorrect: 'When the PA catheter balloon is inflated, the occluded segment creates a static column of blood between the catheter tip and left atrium, allowing PAWP to estimate left atrial and LVEDP.', explanationWrong: 'RVEDP is estimated by CVP. PVR is calculated. RAP is measured at the proximal port. PAWP specifically estimates left-sided filling pressures.', topic: 'Hemodynamic Monitoring' },
      { fullExamId: exam2.id, questionIndex: 63, questionText: 'A patient with chronic kidney disease has pH 7.30, PaCO2 32 mmHg, HCO3- 16 mEq/L, Na+ 140, Cl- 114. The anion gap is 10. This represents:', choices: JSON.stringify({ A: 'Anion gap metabolic acidosis', B: 'Respiratory acidosis', C: 'Non-anion gap (hyperchloremic) metabolic acidosis', D: 'Normal acid-base status' }), correctChoice: 'C', explanationCorrect: 'AG = 140 - (114 + 16) = 10 (normal). Low pH with low HCO3- and normal AG indicates a non-anion gap (hyperchloremic) metabolic acidosis, common in CKD with renal tubular acidosis.', explanationWrong: 'The normal anion gap rules out AGMA. Low PaCO2 is compensatory, not primary. The values are clearly abnormal. Non-anion gap metabolic acidosis is confirmed by the combination.', topic: 'Advanced ABG Interpretation' },
      { fullExamId: exam2.id, questionIndex: 64, questionText: 'Lung-protective ventilation in ARDS aims to prevent ventilator-induced lung injury (VILI). The primary mechanisms of VILI include:', choices: JSON.stringify({ A: 'Volutrauma, barotrauma, atelectrauma, and biotrauma', B: 'Oxygen toxicity only', C: 'Ventilator malfunction', D: 'Medication side effects' }), correctChoice: 'A', explanationCorrect: 'VILI occurs through four mechanisms: volutrauma (overdistension), barotrauma (excessive pressure), atelectrauma (cyclical opening/closing), and biotrauma (inflammatory mediator release from mechanical injury).', explanationWrong: 'Oxygen toxicity is a separate phenomenon. Ventilator malfunction is a device issue. Medications are unrelated. The four-mechanism model of VILI is well established.', topic: 'ARDS Diagnosis and Management' },
      { fullExamId: exam2.id, questionIndex: 65, questionText: 'Hydrocortisone is recommended in septic shock when:', choices: JSON.stringify({ A: 'As a first-line therapy before vasopressors', B: 'Hemodynamic instability persists despite adequate fluid resuscitation and vasopressor therapy', C: 'Only in patients with adrenal insufficiency', D: 'To replace all vasopressor therapy' }), correctChoice: 'B', explanationCorrect: 'The SSC recommends IV hydrocortisone (200 mg/day) when hemodynamic stability cannot be achieved with fluids and vasopressors. It addresses relative adrenal insufficiency and restores vascular catecholamine sensitivity.', explanationWrong: 'Hydrocortisone is not first-line and does not replace vasopressors. While adrenal insufficiency may be present, the indication is refractory shock, not documented insufficiency.', topic: 'Sepsis and Septic Shock' },
      { fullExamId: exam2.id, questionIndex: 66, questionText: 'The A-a gradient on room air in a healthy young adult is approximately:', choices: JSON.stringify({ A: '5-15 mmHg', B: '30-40 mmHg', C: '50-60 mmHg', D: '0 mmHg' }), correctChoice: 'A', explanationCorrect: 'Normal A-a gradient is approximately 5-15 mmHg in young adults, increasing with age (estimated normal = age/4 + 4). An elevated A-a gradient indicates V/Q mismatch, shunt, or diffusion impairment.', explanationWrong: '30-60 mmHg would indicate significant pathology. A gradient of 0 is physiologically impossible due to normal ventilation-perfusion heterogeneity. 5-15 is the normal range.', topic: 'Acute Respiratory Failure' },
      { fullExamId: exam2.id, questionIndex: 67, questionText: 'Inspiratory muscle training (IMT) as a weaning adjunct involves:', choices: JSON.stringify({ A: 'Passive range of motion exercises', B: 'Continuous positive airway pressure', C: 'Incentive spirometry only', D: 'Breathing through a threshold resistive device to strengthen inspiratory muscles' }), correctChoice: 'D', explanationCorrect: 'IMT involves breathing through a threshold resistive device that requires the patient to generate a specific inspiratory pressure to open a valve, progressively strengthening the diaphragm and inspiratory muscles.', explanationWrong: 'Passive ROM exercises the limbs, not respiratory muscles. Incentive spirometry encourages deep breaths but does not provide resistance training. CPAP does not train muscles.', topic: 'Weaning Protocols and SBTs' },
      { fullExamId: exam2.id, questionIndex: 68, questionText: 'The ROX index used with high-flow nasal cannula is calculated as:', choices: JSON.stringify({ A: 'PaO2/FiO2 ratio only', B: 'Respiratory rate times FiO2', C: 'SpO2/FiO2 divided by respiratory rate', D: 'SpO2 divided by respiratory rate' }), correctChoice: 'C', explanationCorrect: 'The ROX index = (SpO2/FiO2)/respiratory rate. A ROX index ≥ 4.88 at 2, 6, or 12 hours predicts HFNC success and lower intubation risk. Values < 3.85 suggest HFNC failure.', explanationWrong: 'P/F ratio alone does not include respiratory rate. RR x FiO2 is not the ROX formula. SpO2/RR alone does not account for FiO2. The ROX index integrates oxygenation efficiency with respiratory effort.', topic: 'NIV in Critical Care' },
      { fullExamId: exam2.id, questionIndex: 69, questionText: 'Complications of prone positioning include all of the following EXCEPT:', choices: JSON.stringify({ A: 'Pressure injuries to face and anterior body', B: 'Endotracheal tube displacement', C: 'Improved cardiac output in all patients', D: 'Brachial plexus injury' }), correctChoice: 'C', explanationCorrect: 'Improved cardiac output is not a universal finding and is not a complication. Actual complications include pressure injuries, ETT displacement, brachial plexus injury, facial edema, and vascular access issues.', explanationWrong: 'Pressure injuries, ETT displacement, and brachial plexus injury are all recognized complications of prone positioning. Improved cardiac output is neither universal nor a complication.', topic: 'Prone Positioning' },
      { fullExamId: exam2.id, questionIndex: 70, questionText: 'Malignant hyperthermia is a life-threatening complication specifically associated with:', choices: JSON.stringify({ A: 'All nondepolarizing NMBAs', B: 'Cisatracurium exclusively', C: 'Anticholinesterase agents', D: 'Succinylcholine and volatile anesthetic agents' }), correctChoice: 'D', explanationCorrect: 'Malignant hyperthermia is triggered by succinylcholine and volatile inhalational anesthetics in genetically susceptible individuals (ryanodine receptor mutation). Treatment is dantrolene sodium.', explanationWrong: 'Nondepolarizing NMBAs do not trigger MH. Cisatracurium is actually safe in MH-susceptible patients. Anticholinesterases do not cause MH. Only succinylcholine and volatiles are triggers.', topic: 'Neuromuscular Blocking Agents' },
      { fullExamId: exam2.id, questionIndex: 71, questionText: 'Delirium in the ICU is associated with all of the following EXCEPT:', choices: JSON.stringify({ A: 'Decreased hospital costs', B: 'Prolonged mechanical ventilation', C: 'Increased mortality', D: 'Longer ICU stay' }), correctChoice: 'A', explanationCorrect: 'Decreased hospital costs is the correct answer because ICU delirium actually INCREASES costs significantly. Delirium is associated with increased mortality, prolonged ventilation, longer ICU/hospital stay, and long-term cognitive impairment.', explanationWrong: 'Increased mortality, prolonged ventilation, and longer ICU stay are all well-documented consequences of ICU delirium. Decreased costs is the false statement - delirium increases costs.', topic: 'Sedation and Pain Management' },
      { fullExamId: exam2.id, questionIndex: 72, questionText: 'Silver-coated endotracheal tubes are designed to reduce VAP by:', choices: JSON.stringify({ A: 'Releasing antibiotics into the airway', B: 'Preventing biofilm formation on the tube surface', C: 'Reducing cuff pressure requirements', D: 'Increasing mucociliary clearance' }), correctChoice: 'B', explanationCorrect: 'Silver-coated ETTs reduce VAP by preventing bacterial biofilm formation on the tube surface. Silver ions have antimicrobial properties that inhibit bacterial adhesion and biofilm development, reducing bacterial colonization.', explanationWrong: 'Silver-coated tubes do not release antibiotics, affect cuff pressure, or enhance mucociliary clearance. Their mechanism is antimicrobial activity against biofilm formation through silver ion release.', topic: 'VAP Prevention' },
      { fullExamId: exam2.id, questionIndex: 73, questionText: 'The oxygenator in an ECMO circuit functions similarly to:', choices: JSON.stringify({ A: 'The native lung', B: 'The native kidney', C: 'The native heart', D: 'The native liver' }), correctChoice: 'A', explanationCorrect: 'The membrane oxygenator functions like the native lung, providing gas exchange by oxygenating blood and removing CO2 across a semipermeable membrane, analogous to the alveolar-capillary membrane.', explanationWrong: 'The oxygenator performs gas exchange like the lungs. The pump replaces cardiac function. The circuit does not perform kidney or liver functions.', topic: 'ECMO' },
      { fullExamId: exam2.id, questionIndex: 74, questionText: 'Surgical emphysema (subcutaneous emphysema) following chest trauma indicates:', choices: JSON.stringify({ A: 'Fat embolism', B: 'Normal healing response', C: 'Air tracking into subcutaneous tissues from a pneumothorax, airway injury, or esophageal perforation', D: 'Internal hemorrhage' }), correctChoice: 'C', explanationCorrect: 'Subcutaneous emphysema indicates air tracking into tissues and suggests pneumothorax, tracheobronchial injury, or esophageal perforation. It presents as crepitus on palpation and requires investigation of the air source.', explanationWrong: 'Subcutaneous emphysema is air in the tissues, not fat, hemorrhage, or normal healing. It warrants investigation for pneumothorax or airway injury as the source of escaped air.', topic: 'Chest Trauma' },
      { fullExamId: exam2.id, questionIndex: 75, questionText: 'Escharotomy in circumferential burns of the chest is performed to:', choices: JSON.stringify({ A: 'Prevent infection', B: 'Restore chest wall compliance and ventilation', C: 'Reduce pain', D: 'Promote wound healing' }), correctChoice: 'B', explanationCorrect: 'Circumferential chest burns create a constrictive eschar that restricts chest wall movement and impairs ventilation. Escharotomy (incision through the eschar) releases the constriction and restores chest wall compliance.', explanationWrong: 'Escharotomy is not primarily for infection prevention, pain reduction, or wound healing. Its purpose is to release the constricting eschar to restore ventilation and/or circulation.', topic: 'Burns and Inhalation Injury' },
      { fullExamId: exam2.id, questionIndex: 76, questionText: 'The bronchodilator reversibility test in COPD uses which criterion for a positive response?', choices: JSON.stringify({ A: 'FEV1 increase of ≥ 5% from baseline', B: 'Peak flow increase of ≥ 50 L/min', C: 'FVC increase of ≥ 5% from baseline', D: 'FEV1 increase of ≥ 12% AND ≥ 200 mL from baseline' }), correctChoice: 'D', explanationCorrect: 'A positive bronchodilator response is defined as FEV1 increase of ≥ 12% AND ≥ 200 mL from baseline, per ATS/ERS criteria. This dual criterion ensures both relative and absolute improvement in airflow.', explanationWrong: '5% change is not significant. FVC alone is not the primary measure. Peak flow changes are not the standard criterion. The dual criterion of ≥12% AND ≥200 mL ensures both relative and absolute improvement.', topic: 'Acute COPD Exacerbation' },
      { fullExamId: exam2.id, questionIndex: 77, questionText: 'IV magnesium sulfate in status asthmaticus acts by:', choices: JSON.stringify({ A: 'Stimulating beta-2 receptors', B: 'Blocking histamine release', C: 'Inhibiting leukotriene synthesis', D: 'Inhibiting calcium-mediated smooth muscle contraction causing bronchodilation' }), correctChoice: 'D', explanationCorrect: 'Magnesium sulfate causes bronchodilation by inhibiting calcium influx into smooth muscle cells, preventing calcium-mediated contraction. It also inhibits acetylcholine release from motor nerve terminals.', explanationWrong: 'Magnesium does not stimulate beta-2 receptors, block histamine, or inhibit leukotrienes. Its mechanism is calcium channel antagonism at the smooth muscle level.', topic: 'Status Asthmaticus' },
      { fullExamId: exam2.id, questionIndex: 78, questionText: 'Submassive (intermediate-risk) PE is characterized by:', choices: JSON.stringify({ A: 'Hemodynamic collapse', B: 'Normal blood pressure with RV dysfunction or elevated troponin/BNP', C: 'Normal hemodynamics and normal RV function', D: 'Incidental finding on CT without symptoms' }), correctChoice: 'B', explanationCorrect: 'Submassive (intermediate-risk) PE is characterized by preserved blood pressure with evidence of RV dysfunction on echocardiography or elevated cardiac biomarkers (troponin, BNP), indicating right heart strain without hemodynamic collapse.', explanationWrong: 'Hemodynamic collapse is massive PE. Normal hemodynamics and RV function is low-risk PE. Incidental findings are low-risk. Submassive PE has normotension with RV strain markers.', topic: 'Pulmonary Embolism' },
      { fullExamId: exam2.id, questionIndex: 79, questionText: 'Ultrasound-guided thoracentesis compared to landmark-based thoracentesis:', choices: JSON.stringify({ A: 'Has a higher complication rate', B: 'Takes significantly longer to perform', C: 'Reduces the risk of pneumothorax', D: 'Is only available in operating rooms' }), correctChoice: 'C', explanationCorrect: 'Ultrasound guidance significantly reduces pneumothorax risk (from ~10% to <2%), improves success rates, and identifies optimal puncture sites. Current guidelines recommend ultrasound guidance for all thoracenteses.', explanationWrong: 'US guidance reduces (not increases) complications. It does not add significant time. Portable US is available at the bedside. The primary benefit is safety improvement.', topic: 'Pleural Diseases' },
      { fullExamId: exam2.id, questionIndex: 80, questionText: 'Alarm fatigue in the ICU is defined as:', choices: JSON.stringify({ A: 'Sensory overload from excessive non-actionable alarms leading to desensitization and delayed response', B: 'Equipment malfunction causing false alarms', C: 'Patient anxiety from alarm sounds', D: 'Insufficient alarm volume settings' }), correctChoice: 'A', explanationCorrect: 'Alarm fatigue is the desensitization of clinicians to alarms due to excessive non-actionable or false alarms, leading to delayed or missed responses to critical alarms. It is a recognized patient safety hazard identified by The Joint Commission.', explanationWrong: 'Alarm fatigue is about clinician desensitization from alarm overload, not equipment malfunction, patient anxiety, or volume settings. It is a major patient safety concern in the ICU.', topic: 'ICU Quality Metrics' },
      { fullExamId: exam2.id, questionIndex: 81, questionText: 'Esophageal pressure monitoring during mechanical ventilation is used to estimate:', choices: JSON.stringify({ A: 'Cardiac output', B: 'Pleural pressure', C: 'Pulmonary artery pressure', D: 'Gastric residual volume' }), correctChoice: 'B', explanationCorrect: 'An esophageal balloon catheter measures esophageal pressure, which approximates pleural pressure. This allows calculation of transpulmonary pressure to guide PEEP titration, particularly in obese patients.', explanationWrong: 'Cardiac output uses thermodilution or Fick. PA pressure uses a Swan-Ganz catheter. Gastric residuals are measured differently. Esophageal pressure estimates pleural pressure.', topic: 'Advanced Mechanical Ventilation' },
      { fullExamId: exam2.id, questionIndex: 82, questionText: 'The thermodilution cardiac output technique may be inaccurate in patients with:', choices: JSON.stringify({ A: 'Severe tricuspid regurgitation', B: 'Normal body temperature', C: 'Adequate hydration', D: 'Normal sinus rhythm' }), correctChoice: 'A', explanationCorrect: 'Thermodilution CO is inaccurate with severe tricuspid regurgitation, which causes retrograde flow that dilutes the indicator over multiple passes, yielding falsely low (not elevated) CO values. Intracardiac shunts also cause errors.', explanationWrong: 'Normal sinus rhythm, temperature, and hydration support accurate thermodilution measurement. Tricuspid regurgitation, intracardiac shunts, and very low CO reduce accuracy.', topic: 'Hemodynamic Monitoring' },
      { fullExamId: exam2.id, questionIndex: 83, questionText: 'Osmolar gap is useful in evaluating metabolic acidosis caused by:', choices: JSON.stringify({ A: 'Diabetic ketoacidosis', B: 'Lactic acidosis', C: 'Renal tubular acidosis', D: 'Toxic alcohol ingestion (methanol, ethylene glycol)' }), correctChoice: 'D', explanationCorrect: 'Osmolar gap is most useful for detecting toxic alcohol ingestion. An elevated osmolar gap (measured minus calculated osmolality > 10) suggests unmeasured osmoles such as methanol, ethylene glycol, or isopropanol.', explanationWrong: 'DKA and lactic acidosis cause elevated AG but not elevated osmolar gap. RTA has a normal AG. Toxic alcohols uniquely elevate both anion gap and osmolar gap.', topic: 'Advanced ABG Interpretation' },
      { fullExamId: exam2.id, questionIndex: 84, questionText: 'PEEP titration using the best compliance method involves:', choices: JSON.stringify({ A: 'Setting PEEP to the highest tolerated level', B: 'Incrementally increasing PEEP and selecting the level that produces the best static compliance (highest VT/driving pressure)', C: 'Using a fixed PEEP of 5 cmH2O for all patients', D: 'Setting PEEP equal to plateau pressure' }), correctChoice: 'B', explanationCorrect: 'The best compliance (or decremental PEEP trial) method incrementally adjusts PEEP and identifies the level with optimal static compliance (VT ÷ driving pressure), indicating maximal alveolar recruitment without overdistension.', explanationWrong: 'Highest tolerated PEEP may overdistend. Fixed PEEP ignores individual physiology. PEEP equal to Pplat provides no driving pressure for ventilation. Best compliance optimizes recruitment.', topic: 'ARDS Diagnosis and Management' },
      { fullExamId: exam2.id, questionIndex: 85, questionText: 'Source control in sepsis refers to:', choices: JSON.stringify({ A: 'Identifying the antibiotic source', B: 'Controlling the source of IV fluids', C: 'Identifying and treating the anatomical source of infection (drainage, debridement, device removal)', D: 'Controlling the patient information source' }), correctChoice: 'C', explanationCorrect: 'Source control involves identifying and eliminating the anatomical focus of infection through procedures such as abscess drainage, debridement of necrotic tissue, removal of infected devices, or definitive repair of perforations.', explanationWrong: 'Source control is a surgical/procedural concept referring to eliminating the nidus of infection, not fluid sources, antibiotic sources, or information management.', topic: 'Sepsis and Septic Shock' },
      { fullExamId: exam2.id, questionIndex: 86, questionText: 'Oxygen delivery (DO2) is calculated by:', choices: JSON.stringify({ A: 'PaO2 multiplied by hemoglobin', B: 'SvO2 x cardiac output', C: 'Tidal volume x respiratory rate x FiO2', D: 'Cardiac output x arterial oxygen content (CaO2) x 10' }), correctChoice: 'D', explanationCorrect: 'DO2 = CO x CaO2 x 10. Normal DO2 is approximately 1000 mL/min. CaO2 = (Hb x 1.34 x SaO2) + (0.003 x PaO2). The factor of 10 converts dL to L.', explanationWrong: 'PaO2 x Hb is incomplete. VT x RR x FiO2 is not DO2. SvO2 x CO is not the standard formula. DO2 requires cardiac output multiplied by arterial oxygen content.', topic: 'Acute Respiratory Failure' },
      { fullExamId: exam2.id, questionIndex: 87, questionText: 'Weaning predictors that should be assessed daily include:', choices: JSON.stringify({ A: 'Patient hair color and weight', B: 'Resolution of underlying cause, adequate oxygenation, hemodynamic stability, and ability to breathe spontaneously', C: 'Blood type and Rh factor', D: 'Insurance status and family preferences' }), correctChoice: 'B', explanationCorrect: 'Daily weaning readiness assessment includes: resolution/improvement of the condition requiring ventilation, adequate oxygenation (FiO2 ≤ 0.40, PEEP ≤ 5-8), hemodynamic stability, and intact respiratory drive.', explanationWrong: 'Hair color, blood type, insurance status, and family preferences are not weaning predictors. Clinical readiness based on physiologic parameters determines weaning eligibility.', topic: 'Weaning Protocols and SBTs' },
      { fullExamId: exam2.id, questionIndex: 88, questionText: 'Auto-CPAP (APAP) differs from fixed CPAP in that it:', choices: JSON.stringify({ A: 'Delivers a fixed pressure throughout the night', B: 'Automatically adjusts pressure based on detected airway events', C: 'Does not require a mask interface', D: 'Is used only in the ICU setting' }), correctChoice: 'B', explanationCorrect: 'Auto-CPAP continuously monitors for airway events (apneas, hypopneas, flow limitation, snoring) and automatically adjusts pressure within a preset range to maintain airway patency with the minimum effective pressure.', explanationWrong: 'Fixed pressure is standard CPAP, not APAP. APAP requires a mask. It is primarily used for outpatient sleep apnea. Automatic pressure adjustment is its defining feature.', topic: 'NIV in Critical Care' },
      { fullExamId: exam2.id, questionIndex: 89, questionText: 'The recommended duration for initial prone positioning sessions is:', choices: JSON.stringify({ A: '≥ 16 consecutive hours', B: '2-4 hours', C: '30 minutes', D: '8 hours maximum' }), correctChoice: 'A', explanationCorrect: 'Based on the PROSEVA trial, prone positioning sessions should last at least 16 consecutive hours per day. Sessions continue until PaO2/FiO2 ≥ 150 on FiO2 ≤ 0.60 with PEEP ≤ 10 for at least 4 hours after supination.', explanationWrong: 'Shorter sessions (2-8 hours) have not demonstrated the same mortality benefit. The PROSEVA protocol mandating ≥ 16 hours is the evidence-based standard.', topic: 'Prone Positioning' },
      { fullExamId: exam2.id, questionIndex: 90, questionText: 'The train-of-four (TOF) target for adequate neuromuscular blockade during continuous infusion is:', choices: JSON.stringify({ A: '4 of 4 twitches', B: '3 of 4 twitches', C: '1-2 of 4 twitches', D: '0 of 4 twitches' }), correctChoice: 'C', explanationCorrect: 'A TOF goal of 1-2 twitches out of 4 provides adequate paralysis for ventilator synchrony while avoiding complete blockade. Zero twitches indicates excessive paralysis; 3-4 indicates insufficient blockade.', explanationWrong: '4/4 is normal (no blockade). 3/4 is light blockade. 0/4 is excessive and increases risk of prolonged weakness. 1-2/4 is the therapeutic target.', topic: 'Neuromuscular Blocking Agents' },
      { fullExamId: exam2.id, questionIndex: 91, questionText: 'Daily sedation interruption (spontaneous awakening trial) has been shown to:', choices: JSON.stringify({ A: 'Increase duration of mechanical ventilation', B: 'Increase incidence of self-extubation with worse outcomes', C: 'Reduce duration of mechanical ventilation and ICU length of stay', D: 'Have no effect on patient outcomes' }), correctChoice: 'C', explanationCorrect: 'The landmark Kress et al. study demonstrated that daily sedation interruption reduces duration of mechanical ventilation and ICU LOS. When paired with SBTs (Girard ABC trial), benefits are magnified.', explanationWrong: 'Daily awakening trials reduce (not increase) ventilation duration. While self-extubation risk exists, net outcomes improve. Multiple studies confirm significant benefit.', topic: 'Sedation and Pain Management' },
      { fullExamId: exam2.id, questionIndex: 92, questionText: 'The mini-BAL (blind bronchial sampling) is used in VAP diagnosis to:', choices: JSON.stringify({ A: 'Replace chest X-ray', B: 'Administer antibiotics directly to the lungs', C: 'Measure pleural fluid', D: 'Obtain lower respiratory tract cultures without bronchoscopy' }), correctChoice: 'D', explanationCorrect: 'Mini-BAL obtains lower respiratory tract cultures by advancing a catheter blindly through the ETT into a distal airway and performing lavage. It provides quantitative cultures without requiring bronchoscopy.', explanationWrong: 'Mini-BAL does not replace CXR, measure pleural fluid, or deliver medications. It is a sampling technique for obtaining quantitative cultures from the lower airway.', topic: 'VAP Prevention' },
      { fullExamId: exam2.id, questionIndex: 93, questionText: 'ECMO weaning trials involve:', choices: JSON.stringify({ A: 'Abruptly stopping the ECMO circuit', B: 'Stopping anticoagulation first', C: 'Replacing ECMO with NIV', D: 'Gradually reducing ECMO support while optimizing ventilator settings to assess native organ function' }), correctChoice: 'D', explanationCorrect: 'ECMO weaning involves gradually reducing ECMO support by decreasing blood flow while optimizing ventilator settings, assessing whether native organ function can sustain adequate gas exchange or hemodynamics.', explanationWrong: 'Abrupt cessation risks hemodynamic collapse. Anticoagulation must continue while circuit is running. NIV is not a direct replacement. Gradual weaning with native function assessment is standard.', topic: 'ECMO' },
      { fullExamId: exam2.id, questionIndex: 94, questionText: 'Damage control resuscitation in massive trauma includes:', choices: JSON.stringify({ A: 'Aggressive crystalloid resuscitation with 10L or more of saline', B: 'Withholding all blood products until cross-matched', C: 'Liberal use of hypotonic solutions', D: 'Balanced transfusion of packed RBCs, plasma, and platelets in 1:1:1 ratio' }), correctChoice: 'D', explanationCorrect: 'Damage control resuscitation uses balanced blood component therapy (1:1:1 ratio of pRBCs:FFP:platelets) based on the PROPPR trial, limits crystalloid use, targets permissive hypotension, and addresses the lethal triad (hypothermia, acidosis, coagulopathy).', explanationWrong: 'Aggressive crystalloid causes dilutional coagulopathy. Waiting for crossmatch delays resuscitation. Hypotonic solutions worsen edema. Balanced transfusion is the evidence-based approach.', topic: 'Chest Trauma' },
      { fullExamId: exam2.id, questionIndex: 95, questionText: 'Carboxyhemoglobin levels above what percentage are considered significant in carbon monoxide poisoning?', choices: JSON.stringify({ A: '1-2%', B: '3-5%', C: '> 10-15%', D: '> 50%' }), correctChoice: 'C', explanationCorrect: 'COHb levels > 10-15% are considered clinically significant. Non-smokers normally have < 3%, smokers up to 10%. Levels > 25% cause significant symptoms, and > 60% are often fatal.', explanationWrong: '1-5% can be normal in smokers or from endogenous production. > 50% is often lethal. > 10-15% is the threshold for clinically significant CO poisoning requiring treatment.', topic: 'Burns and Inhalation Injury' },
      { fullExamId: exam2.id, questionIndex: 96, questionText: 'Systemic corticosteroids in acute COPD exacerbation should be administered for:', choices: JSON.stringify({ A: '5-7 days', B: '21-28 days', C: '1-2 days only', D: 'Indefinitely' }), correctChoice: 'A', explanationCorrect: 'Current evidence (REDUCE trial) supports a 5-day course of systemic corticosteroids (prednisone 40 mg or equivalent) for acute COPD exacerbation, which is non-inferior to the traditional 14-day course.', explanationWrong: '21-28 days is excessive and increases side effects. 1-2 days is insufficient. Indefinite use causes serious adverse effects. Short-course (5-7 days) is evidence-based.', topic: 'Acute COPD Exacerbation' },
      { fullExamId: exam2.id, questionIndex: 97, questionText: 'Isocyanate exposure in industrial settings can cause:', choices: JSON.stringify({ A: 'Occupational asthma', B: 'Pulmonary fibrosis only', C: 'Kidney failure', D: 'Liver cirrhosis' }), correctChoice: 'A', explanationCorrect: 'Isocyanates (used in polyurethane production, spray painting, and adhesives) are the most common cause of occupational asthma. They cause both sensitizer-induced and irritant-induced asthma through immune and non-immune mechanisms.', explanationWrong: 'While high-dose exposure can cause pulmonary injury, occupational asthma is the primary clinical concern. Kidney and liver effects are not typical of isocyanate exposure.', topic: 'Status Asthmaticus' },
      { fullExamId: exam2.id, questionIndex: 98, questionText: 'IVC filter placement for PE is indicated when:', choices: JSON.stringify({ A: 'Anticoagulation is contraindicated or has failed', B: 'All patients with PE require IVC filters', C: 'The patient has mild PE with no complications', D: 'Prophylactically in all surgical patients' }), correctChoice: 'A', explanationCorrect: 'IVC filters are indicated when anticoagulation is absolutely contraindicated (active hemorrhage, recent surgery) or has failed (recurrent PE despite adequate anticoagulation). Retrievable filters are preferred.', explanationWrong: 'Not all PE patients need filters. Mild PE is managed with anticoagulation alone. Prophylactic filter placement is not standard. Filters are reserved for anticoagulation failure or contraindication.', topic: 'Pulmonary Embolism' },
      { fullExamId: exam2.id, questionIndex: 99, questionText: 'Light criteria for exudative pleural effusion require meeting at least:', choices: JSON.stringify({ A: 'All three criteria simultaneously', B: 'Any two of three criteria', C: 'One of three criteria', D: 'None of the criteria (clinical judgment only)' }), correctChoice: 'C', explanationCorrect: 'Meeting ANY ONE of the three Light criteria classifies an effusion as exudative: (1) pleural/serum protein > 0.5, (2) pleural/serum LDH > 0.6, or (3) pleural LDH > 2/3 upper limit of normal serum LDH.', explanationWrong: 'Only one criterion needs to be met, not two or all three. Clinical judgment alone is insufficient. The sensitivity of requiring only one criterion is intentionally high (~98%).', topic: 'Pleural Diseases' },
      { fullExamId: exam2.id, questionIndex: 100, questionText: 'Early mobilization in the ICU has been associated with:', choices: JSON.stringify({ A: 'Increased ventilator days', B: 'Higher complication rates', C: 'No effect on outcomes', D: 'Reduced ICU and hospital length of stay, improved functional outcomes' }), correctChoice: 'D', explanationCorrect: 'Early mobilization programs in the ICU reduce ventilator days, ICU and hospital LOS, improve functional capacity at discharge, and reduce delirium. Safety data show low adverse event rates during mobilization.', explanationWrong: 'Early mobilization decreases (not increases) ventilator days. Complication rates are low. Multiple RCTs demonstrate significant outcome benefits from early mobility programs.', topic: 'ICU Quality Metrics' }
    ],
  })

